import {serviceShadow} from './approved-service-host.js';
const markup="<div id=\"gv-help-service\"><div class=\"stage\">\n <section class=\"window\" id=\"help-window\" aria-labelledby=\"help-title\">\n  <header class=\"head\"><span class=\"mark\" aria-hidden=\"true\">?</span><h2 id=\"help-title\">Como jogar</h2><button type=\"button\" class=\"close cursor-interaction\" id=\"help-close\" aria-label=\"Fechar\">×</button></header>\n  <nav class=\"tabs\" aria-label=\"Guia do jogo\"><button type=\"button\" class=\"button cursor-interaction\" id=\"help-controls-tab\" aria-pressed=\"true\" aria-controls=\"help-controls\">Controles</button><button type=\"button\" class=\"button cursor-interaction\" id=\"help-progress-tab\" aria-pressed=\"false\" aria-controls=\"help-progress\">Progressão</button></nav>\n  <div class=\"body\">\n   <section class=\"pane\" id=\"help-controls\" aria-labelledby=\"help-controls-tab\">\n    <div class=\"play-grid\">\n     <div class=\"panel core\"><h3>Golpe no pulso</h3><div class=\"pulse\" aria-hidden=\"true\"><span></span><span></span><span></span><span></span><span></span><span></span></div><div class=\"keyline\"><span>Clique</span><span>ou</span><kbd>Espaço</kbd></div><p>Errou → perde fôlego</p></div>\n     <div class=\"panel core\"><h3>Mover</h3><div class=\"wasd\" aria-label=\"Teclas W, A, S e D\"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd></div><p>ou setas / clique no chão</p><p>Ataques → −vida</p></div>\n    </div>\n    <div class=\"items\" aria-label=\"Consumíveis usados no pulso\"><div class=\"item\"><img src=\"assets/hud-v5/blast.png\" alt=\"\"><div><kbd>1</kbd><b>Bomba</b></div></div><div class=\"item\"><img src=\"assets/hud-v5/tonic.png\" alt=\"\"><div><kbd>2</kbd><b>Cura</b></div></div><div class=\"item\"><img src=\"assets/hud-v5/ward.png\" alt=\"\"><div><kbd>3</kbd><b>Escudo</b></div></div></div>\n    <div class=\"quick\"><div class=\"shortcut\"><span class=\"keyline\"><kbd>ESC</kbd><span>/</span><kbd>P</kbd></span><span>Pausa</span></div><div class=\"shortcut\"><kbd>E</kbd><span>Resgate</span></div><div class=\"shortcut\"><kbd>Tab</kbd><span>Talentos</span></div><div class=\"shortcut\"><kbd>Q</kbd><span>Alvo</span></div></div>\n   </section>\n   <section class=\"pane\" id=\"help-progress\" aria-labelledby=\"help-progress-tab\" aria-hidden=\"true\" inert>\n    <div class=\"rules\">\n     <div class=\"rule\"><div class=\"rule-icons\"><img src=\"assets/hud-v5/heart.png\" alt=\"Vida\"><span>/</span><img src=\"assets/hud-v5/breath.png\" alt=\"Fôlego\"></div><strong>0 → fim da descida</strong></div>\n     <div class=\"rule\"><b>Cartas</b><strong>Só nesta descida</strong></div>\n     <div class=\"loot\"><div class=\"rule\"><img src=\"assets/refuge-night-v3/lift.png\" alt=\"\"><strong>Elevador pronto<small>Todo o saque</small></strong></div><div class=\"rule\"><img src=\"assets/hud-v5/home.png\" alt=\"\"><strong>Resgate / derrota<small>Saque parcial</small></strong></div></div>\n     <div class=\"services\"><div class=\"service\"><img src=\"assets/forge-v6/anvil-v05-attempt-3-256.png\" alt=\"\"><div><b>Forja</b><span>Equipamentos</span></div></div><div class=\"service\"><img src=\"assets/refuge-night-v3/echo-tree.png\" alt=\"\"><div><b>Árvore</b><span>Talentos</span></div></div><div class=\"service\"><img src=\"assets/approved-reliquary-v1/emblem.webp\" alt=\"\"><div><b>Relicário</b><span>Melhorias ★</span></div></div></div>\n    </div>\n   </section>\n  </div>\n  <footer class=\"footer\"><button type=\"button\" class=\"button primary cursor-interaction\" id=\"helpDone\">Jogar</button></footer>\n </section>\n</div>\n</div>";
export function mountApprovedHelp(dialog,{onClose,softMode=()=>false}={}){
 const doc=dialog.ownerDocument,shadow=serviceShadow(dialog,markup),style=doc.createElement('link');
 style.rel='stylesheet';style.href='approved-help-ui.css';shadow.prepend(style);
 const root=shadow.querySelector('#gv-help-service'),q=id=>root.querySelector('#'+id),media=doc.defaultView.matchMedia('(prefers-reduced-motion:reduce)');
 const previousLabel=dialog.getAttribute('aria-label');dialog.setAttribute('aria-label','Como jogar');
 let selected='controls',animation=null,disposed=false;const cleanups=[];
 const listen=(target,event,fn)=>{target.addEventListener(event,fn);cleanups.push(()=>target.removeEventListener(event,fn));};
 function cancel(){animation?.cancel();animation=null;}
 function render(){cancel();for(const tab of ['controls','progress']){const active=selected===tab;q('help-'+tab+'-tab').setAttribute('aria-pressed',String(active));q('help-'+tab).setAttribute('aria-hidden',String(!active));q('help-'+tab).inert=!active;}}
 function select(tab){if(disposed||selected===tab)return;selected=tab;render();if(!softMode()&&!media.matches)animation=q('help-'+tab).animate([{transform:'translateY(4px)'},{transform:'translateY(0)'}],{duration:140,easing:'ease-out'});}
 function close(){if(!disposed)onClose();}
 for(const tab of ['controls','progress'])listen(q('help-'+tab+'-tab'),'click',()=>select(tab));
 listen(q('help-close'),'click',close);listen(q('helpDone'),'click',close);
 listen(root,'keydown',e=>{
  if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();return;}
  if(e.key==='Tab'){
   const buttons=[...root.querySelectorAll('button:not(:disabled)')].filter(b=>!b.closest('[inert]')&&b.getClientRects().length),i=buttons.indexOf(shadow.activeElement);
   if(buttons.length&&(i<0||e.shiftKey&&i===0||!e.shiftKey&&i===buttons.length-1)){e.preventDefault();buttons[e.shiftKey?buttons.length-1:0].focus({preventScroll:true});}
   e.stopPropagation();
  }
 });
 listen(media,'change',cancel);render();q('help-close').focus({preventScroll:true});
 return ()=>{if(disposed)return;disposed=true;cancel();for(const fn of cleanups)fn();if(previousLabel===null)dialog.removeAttribute('aria-label');else dialog.setAttribute('aria-label',previousLabel);};
}
